function objectiveFor(scene: Scene, phase: CeremonyPhase, dialogueOpen: boolean): string {
  if (dialogueOpen) return 'Press E to continue the dialogue';
  switch (scene) {
    case 'intro':
      return 'The ceremony awaits — begin when ready';
    case 'entrance':
      return 'Walk to the access gate and swipe your card';
    case 'swipe':
      return 'Swipe your student card through the reader';
    case 'passage':
      return 'Walk to the stairs and go up';
    case 'hall':
      return 'Walk down the carpet to meet the Dean';
    case 'ceremony':
      if (phase === 'kneelPrompt') return 'Press E to kneel';
      if (phase === 'knighting') return 'Hold still — the knighting is underway';
      return 'Listen to the Dean';
    case 'celebration':
      return "You are a UCT Sci Knight";
    case 'complete':
      return 'Mission complete';
  }
}


interface Props {
  onExitToMap: () => void;
}

interface PendingDialogue {
  id: number;
  lines: DialogueLine[];
  onDone: () => void;
}

export function SciKnightCeremony({ onExitToMap }: Props) {
  const { profile } = usePlayer();
  const playerSprites = avatarById(profile?.selected_avatar).sprites;
  const [scene, setScene] = useState<Scene>('intro');
  const [phase, setPhase] = useState<CeremonyPhase>('greet');
  const [dialogue, setDialogue] = useState<PendingDialogue | null>(null);

  const entranceZones = useMemo(() => [ENTRANCE_ACCESS_ZONE], []);
  const passageZones = useMemo(() => [PASSAGE_STAIRS_ZONE], []);
  const hallNpcs = useMemo(() => [DEAN_NPC], []);
  
  const ceremonyNpcs = useMemo(
    () => hallNpcs.map((n) => (n.id === 'dean' ? { ...n, interactionLabel: undefined } : n)),
    [hallNpcs],
  );

  const dialogueIdRef = useRef(0);
  const openDialogue = useCallback((lines: DialogueLine[], onDone: () => void) => {
    dialogueIdRef.current += 1;
    setDialogue({ id: dialogueIdRef.current, lines, onDone });
  }, []);
  const closeDialogue = useCallback(() => setDialogue(null), []);

  const handleEntranceInteract = useCallback((id: string) => {
    if (id === ENTRANCE_ACCESS_ZONE.id) {
      setScene('swipe');
    }
  }, []);

  const handleSwipeSuccess = useCallback(() => setScene('passage'), []);

  const handlePassageInteract = useCallback((id: string) => {
    if (id === PASSAGE_STAIRS_ZONE.id) {
      setScene('hall');
    }
  }, []);

  const handleHallInteract = useCallback((id: string) => {
    if (id === 'dean') {
      setScene('ceremony');
      setPhase('greet');
    }
  }, []);

  
  useEffect(() => {
    if (scene !== 'ceremony') return;

    if (phase === 'greet') {
      openDialogue(DEAN_GREET_LINES, () => {
        closeDialogue();
        setPhase('pivot');
      });
    } else if (phase === 'pivot') {
      openDialogue(DEAN_PIVOT_LINES, () => {
        closeDialogue();
        setPhase('kneelPrompt');
      });
    } else if (phase === 'rise') {
      openDialogue(DEAN_RISE_LINES, () => {
        closeDialogue();
        setPhase('done');
      });
    }
  }, [scene, phase, openDialogue, closeDialogue]);

  
  useKeyPress(
    'e',
    () => setPhase('knighting'),
    scene === 'ceremony' && phase === 'kneelPrompt' && !dialogue,
  );


  const KNIGHTING_DURATION_MS = 4200;
  useEffect(() => {
    if (scene !== 'ceremony' || phase !== 'knighting') return;
    const t = window.setTimeout(() => setPhase('rise'), KNIGHTING_DURATION_MS);
    return () => window.clearTimeout(t);
  }, [scene, phase]);


  useEffect(() => {
    if (scene !== 'ceremony' || phase !== 'done') return;
    const t = window.setTimeout(() => {
      setScene('celebration');
    }, 400);
    return () => window.clearTimeout(t);
  }, [scene, phase]);

  const dialogueOpen = dialogue !== null;

  const ceremonyDimmed =
    scene === 'ceremony' && (phase === 'knighting' || phase === 'rise');
  const ceremonyPlayerLock =
    scene === 'ceremony' ? CEREMONY_PLAYER_LOCK : undefined;
  const ceremonyPlayerClass =
    scene === 'ceremony' && (phase === 'knighting' || phase === 'rise' || phase === 'done')
      ? 'bg-scene__player--kneel'
      : undefined;

  return (
    <div className="skc-mission">
      <header className="skc-mission__hud">
        <div className="skc-mission__title">
          <span className="skc-mission__eyebrow">The Ceremony · Final Scene</span>
          Rise, Sci Knight
        </div>
        <div className="skc-mission__objective">{objectiveFor(scene, phase, dialogueOpen)}</div>
      </header>

      <div className="skc-mission__stage">
        {scene === 'intro' && <IntroCard onStart={() => setScene('entrance')} />}

        {scene === 'entrance' && (
          <BackgroundScene
            backgroundSrc={entranceBg}
            playerSprites={playerSprites}
            spawn={ENTRANCE_SPAWN}
            bounds={ENTRANCE_BOUNDS}
            zones={entranceZones}
            interactionEnabled={!dialogueOpen}
            onInteract={handleEntranceInteract}
          />
        )}

        {scene === 'swipe' && (
          <>
            {/* Keep the entrance visible beneath the swipe overlay so the
                transition doesn't cut to black. Movement is frozen below;
                the player is parked next to the access gate. */}
            <BackgroundScene
              backgroundSrc={entranceBg}
              playerSprites={playerSprites}
              spawn={{ x: ENTRANCE_ACCESS_ZONE.x - 6, y: ENTRANCE_ACCESS_ZONE.y + 10 }}
              bounds={ENTRANCE_BOUNDS}
              interactionEnabled={false}
              onInteract={() => {}}
            />
            <CardSwipeMinigame onSuccess={handleSwipeSuccess} />
          </>
        )}

        {scene === 'passage' && (
          <BackgroundScene
            backgroundSrc={passageBg}
            playerSprites={playerSprites}
            spawn={PASSAGE_SPAWN}
            bounds={PASSAGE_BOUNDS}
            zones={passageZones}
            interactionEnabled={!dialogueOpen}
            onInteract={handlePassageInteract}
          />
        )}

        {scene === 'hall' && (
          <BackgroundScene
            backgroundSrc={hallBg}
            playerSprites={playerSprites}
            spawn={HALL_SPAWN}
            bounds={HALL_BOUNDS}
            npcs={hallNpcs}
            interactionEnabled={!dialogueOpen}
            onInteract={handleHallInteract}
          />
        )}

        {scene === 'ceremony' && (
          <BackgroundScene
            backgroundSrc={hallBg}
            playerSprites={playerSprites}
            spawn={HALL_SPAWN}
            bounds={HALL_BOUNDS}
            npcs={ceremonyNpcs}
            interactionEnabled={false}
            onInteract={() => {}}
            playerLockPos={ceremonyPlayerLock}
            playerLockFacing="up"
            playerClass={ceremonyPlayerClass}
            overlay={
              <>
                {ceremonyDimmed && <div className="skc-dim" />}
                {ceremonyDimmed && <div className="skc-spotlight" />}
                {scene === 'ceremony' && phase === 'knighting' && <KnightingSword />}
                {scene === 'ceremony' && phase === 'kneelPrompt' && (
                  <KneelPrompt />
                )}
              </>
            }
          />
        )}

        {scene === 'celebration' && (
          <>
            <BackgroundScene
              backgroundSrc={hallBg}
              playerSprites={playerSprites}
              spawn={HALL_SPAWN}
              bounds={HALL_BOUNDS}
              npcs={ceremonyNpcs}
              interactionEnabled={false}
              onInteract={() => {}}
              playerLockPos={CEREMONY_PLAYER_LOCK}
              playerLockFacing="up"
            />
            <Confetti />
            <CelebrationCard onContinue={() => setScene('complete')} />
          </>
        )}

        {scene === 'complete' && <CompleteCard onContinue={onExitToMap} />}

        {dialogue && (
          <DialogueBox key={dialogue.id} lines={dialogue.lines} onComplete={dialogue.onDone} />
        )}
      </div>
    </div>
  );
}


